 * 改签与第三方发布竞争同一时隙时按事务提交顺序裁决，第三方抢不到改签后已占用的时隙。
 */
@SpringBootTest
class PlanRescheduleConcurrencyTest {

    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
