                        String routeId, Instant startUtc, Instant endUtc) {
}
'@
[System.IO.File]::WriteAllText("$base\src\main\java\com\example\starter\plan\model\Occupancy.java", $occupancy, $enc)

$publishedSlot = @'
package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 已发布计划的一条生效时隙（跨计划冲突检测与查询结果共用）。
 *
 * @param scheduleKey 所属计划业务键
 * @param trainNo     列车编号
 * @param sectionId   区段 ID
 * @param routeId     可选进路编号，null 表示不参与进路互斥
 * @param startUtc    占用开始（含），UTC
 * @param endUtc      占用结束（不含），UTC
