package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.Instant;

/**
 * 区段占用请求项，区间左闭右开，起止均为 UTC 时刻。
 * routeId 可选，缺省表示该占用不参与进路互斥。
 */
public record OccupancyRequest(
        @NotBlank String trainNo,
        @NotBlank String sectionId,
        @Size(max = 64) String routeId,
        @NotNull Instant startUtc,
        @NotNull Instant endUtc) {
}
'@
[System.IO.File]::WriteAllText("$dto\OccupancyRequest.java", $occReq, $enc)

$occView = @'
package com.example.starter.plan.web.dto;

import java.time.Instant;

/**
 * 占用视图，起止为 UTC 时刻，区间左闭右开；routeId 为 null 表示不参与进路互斥。
 */
public record OccupancyView(String trainNo, String sectionId, String routeId,
                            Instant startUtc, Instant endUtc) {
}
'@
[System.IO.File]::WriteAllText("$dto\OccupancyView.java", $occView, $enc)

$slotView = @'
package com.example.starter.plan.web.dto;

import java.time.Instant;

/**
 * 已发布时隙视图，用于按日期与区段查询当前生效占用；routeId 为 null 表示不参与进路互斥。
 */
public record PublishedSlotView(String scheduleKey, String trainNo, String sectionId,
                                String routeId, Instant startUtc, Instant endUtc) {
}
'@
[System.IO.File]::WriteAllText("$dto\PublishedSlotView.java", $slotView, $enc)

$createRoute = @'
package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
