$pairReq = @'
package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 进路冲突对请求项，方向无关（对称）。
 */
public record ConflictPairRequest(@NotBlank String routeA, @NotBlank String routeB) {
}
'@
[System.IO.File]::WriteAllText("$dto\ConflictPairRequest.java", $pairReq, $enc)

$pairView = @'
package com.example.starter.plan.web.dto;

/**
 * 进路冲突对视图，按字典序规范化输出（routeA <= routeB）。
 */
public record ConflictPairView(String routeA, String routeB) {
}
'@
[System.IO.File]::WriteAllText("$dto\ConflictPairView.java", $pairView, $enc)

$updateMatrix = @'
package com.example.starter.plan.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.util.List;

/**
 * 更新进路冲突矩阵请求：expectedVersion 必须与当前矩阵版本一致，成功版本加一。
 * requestId 为幂等键；operator 为操作者标识，计入幂等身份。
 * addConflicts / removeConflicts 为空列表表示不变更对应方向。
 */
public record UpdateRouteMatrixRequest(
        @NotBlank String requestId,
        @NotBlank String operator,
        @NotNull Integer expectedVersion,
        @NotNull List<@Valid ConflictPairRequest> addConflicts,
        @NotNull List<@Valid ConflictPairRequest> removeConflicts) {
}
'@
[System.IO.File]::WriteAllText("$dto\UpdateRouteMatrixRequest.java", $updateMatrix, $enc)

$matrixResp = @'
package com.example.starter.plan.web.dto;

import java.util.List;

/**
 * 进路冲突矩阵视图：当前版本、全部已注册进路与规范化后的对称冲突对。
 */
public record RouteMatrixResponse(int version, List<String> routes,
                                  List<ConflictPairView> conflicts) {
}
'@
[System.IO.File]::WriteAllText("$dto\RouteMatrixResponse.java", $matrixResp, $enc)
Write-Output 'dtos done'

