'        return jdbc.query(sql.toString(), (rs, n) -> new PublishedSlot(' + "`r`n" + '                rs.getString("schedule_key"),' + "`r`n" + '                rs.getString("train_no"),' + "`r`n" + '                rs.getString("section_id"),' + "`r`n" + '                rs.getString("route_id"),')

